import{_ as n,o,c as t,a2 as a}from"./chunks/framework.Desnpdez.js";const r="/mbit-mcpo-proxy-download/guide/images/integrations-open-webui-full.png",s="/mbit-mcpo-proxy-download/guide/images/guides/open-webui-01-profile-settings.png",i="/mbit-mcpo-proxy-download/guide/images/guides/open-webui-02-integrations.png",l="/mbit-mcpo-proxy-download/guide/images/guides/open-webui-03-add-connection.png",f=JSON.parse('{"title":"Open WebUI","description":"","frontmatter":{},"headers":[],"relativePath":"everyday/open-webui.md","filePath":"everyday/open-webui.md"}'),d={name:"everyday/open-webui.md"};function p(c,e,g,h,m,u){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="open-webui" tabindex="-1">Open WebUI <a class="header-anchor" href="#open-webui" aria-label="Permalink to &quot;Open WebUI&quot;">​</a></h1><p>Use this page when your chats run in <strong><a href="https://openwebui.com/" target="_blank" rel="noreferrer">Open WebUI</a></strong> (self-hosted or company-hosted).</p><h2 id="automatic-sync-recommended" tabindex="-1">Automatic sync (recommended) <a class="header-anchor" href="#automatic-sync-recommended" aria-label="Permalink to &quot;Automatic sync (recommended)&quot;">​</a></h2><ol><li>In Open WebUI, open your <strong>profile (bottom left) → Settings → Account → API keys</strong>. Reveal and copy the <strong>API key</strong>.</li><li>In <strong>MindBehindAI</strong>, open <strong>Integrations → Open WebUI</strong>.</li><li>Paste your <strong>Open WebUI URL</strong> (only the main site—nothing after <code>/</code>).</li><li>Paste the <strong>API key</strong>.</li><li>Tap <strong>Save</strong>, then <strong>Sync enabled connections</strong>.</li></ol><p>MindBehindAI updates <strong>Integrations → Tool servers</strong> in Open WebUI for <strong>this computer</strong> only—other machines are left alone.</p><p><img src="'+r+'" alt="Open WebUI integration page in MindBehindAI"></p><h2 id="manual-setup-same-computer" tabindex="-1">Manual setup (same computer) <a class="header-anchor" href="#manual-setup-same-computer" aria-label="Permalink to &quot;Manual setup (same computer)&quot;">​</a></h2><p>If <strong>MindBehindAI</strong> and Open WebUI run on <strong>the same computer</strong>, you can skip sync and add each tool by hand:</p><ol><li>On <strong>Home</strong>, under <strong>Links for other apps</strong>, tap <strong>Copy link</strong> for each connection.</li><li>In Open WebUI, go to <strong>Admin → Settings → External tools</strong> (labels vary by version) and add one entry per link.</li></ol><p>The app shows three small screenshots you can tap to enlarge. The same steps are reproduced here:</p><h3 id="step-1–2-profile-and-settings" tabindex="-1">Step 1–2: Profile and Settings <a class="header-anchor" href="#step-1–2-profile-and-settings" aria-label="Permalink to &quot;Step 1–2: Profile and Settings&quot;">​</a></h3><p><img src="'+s+'" alt="Open WebUI profile and settings"></p><h3 id="step-3–4-integrations-and-tool-servers" tabindex="-1">Step 3–4: Integrations and tool servers <a class="header-anchor" href="#step-3–4-integrations-and-tool-servers" aria-label="Permalink to &quot;Step 3–4: Integrations and tool servers&quot;">​</a></h3><p><img src="'+i+'" alt="Open WebUI integrations"></p><h3 id="step-5–7-add-connection" tabindex="-1">Step 5–7: Add connection <a class="header-anchor" href="#step-5–7-add-connection" aria-label="Permalink to &quot;Step 5–7: Add connection&quot;">​</a></h3><p><img src="'+l+'" alt="Open WebUI add connection"></p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>For <strong>MindBehind tool URLs</strong> on this computer, use the same <strong><code>http://127.0.0.1:…</code></strong> addresses as <strong>Home</strong> → <strong>Links for other apps</strong> (or run <strong>Sync enabled connections</strong>). That matches what the app writes and works reliably in the embedded <strong>Chat</strong> webview; plain <strong><code>localhost</code></strong> can fail there even when it works in a normal browser tab.</li><li>If Open WebUI runs <strong>inside Docker</strong> on the same machine, try <code>http://host.docker.internal:PORT/…</code> instead of loopback for reaching the host bridge.</li><li>After changing which connections are enabled, run <strong>Sync enabled connections</strong> again.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><strong><a href="./home.html">Home</a></strong> — copy links without Open WebUI.</li><li><strong><a href="./../help/troubleshooting.html">Troubleshooting</a></strong> — if sync fails or tools do not appear.</li></ul>',20)])])}const y=n(d,[["render",p]]);export{f as __pageData,y as default};
